// Tests of iceberg::rendering::calibrate_ambisonics(), the calibration of the mono signal
// that feeds the late (Ambisonics) branch: the filter and level factor of the loudspeaker
// nearest the source, RMS normalisation and SPL scaling. It is compared with the reference
// data generated by Iceberg MATLAB v1.0.0 and checked on synthetic noise and edge cases.

#include "io/calibration_loader.h"
#include "io/wav_loader.h"
#include "rendering/calibrate_ambisonics.h"
#include "iceberg_signal.h"
#include "test_helpers.h"

#include <gtest/gtest.h>

#include <Eigen/Dense>

#include <chrono>
#include <cmath>
#include <cstdio>
#include <limits>
#include <random>
#include <string>

namespace {

constexpr double kFs = 44100.0;

using iceberg::test::record_measure;

iceberg::rendering::ConfigSetup default_setup() {
    return iceberg::test::load_case_setup(std::string("sweep/rt_05"));
}

iceberg::Signal white_noise_mono(int n, unsigned seed = 42) {
    std::mt19937 rng(seed);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
    iceberg::Signal s;
    s.samples = Eigen::MatrixXf(n, 1);
    for (int i = 0; i < n; ++i) {
        s.samples(i, 0) = dist(rng);
    }
    s.sample_rate = kFs;
    return s;
}

// With the default layout and calibration, 1024 samples of white noise at 45 deg and
// 80 dB SPL give a one-channel output with the length and sample rate of the input,
// without NaN and not all zero.
TEST(CalibrateAmbisonics, HappyPathFixture) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto cfg = default_setup();
    const auto signal = white_noise_mono(1024);

    const auto out = iceberg::rendering::calibrate_ambisonics(
        signal, /*level_db=*/80.0, /*source_angle_deg=*/45.0, cfg);

    EXPECT_EQ(out.samples.cols(), 1);
    EXPECT_EQ(out.samples.rows(), signal.samples.rows());
    EXPECT_DOUBLE_EQ(out.sample_rate, kFs);
    EXPECT_FALSE(out.samples.array().isNaN().any());
    EXPECT_GT(out.samples.cwiseAbs().maxCoeff(), 0.0f);
}

// A NaN level (level 'n' in Iceberg MATLAB) skips the SPL scaling: on white noise at
// 45 deg the output contains no NaN and differs from the output at 80 dB SPL (largest
// difference above 1e-6).
TEST(CalibrateAmbisonics, NaNLevelSkipsSplScaling) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto cfg = default_setup();
    const auto signal = white_noise_mono(1024);

    const auto with_level = iceberg::rendering::calibrate_ambisonics(
        signal, 80.0, 45.0, cfg);
    const auto skip_level = iceberg::rendering::calibrate_ambisonics(
        signal, std::numeric_limits<double>::quiet_NaN(), 45.0, cfg);

    EXPECT_FALSE(skip_level.samples.array().isNaN().any());
    // Outputs must differ — the SPL multiplier was either applied or not.
    const double diff = (with_level.samples - skip_level.samples)
                            .cwiseAbs().maxCoeff();
    EXPECT_GT(diff, 1e-6f);
}

// A level above the 95 dB SPL maximum (96 dB) is rejected with std::invalid_argument.
TEST(CalibrateAmbisonics, ThrowsOnLevelAbove95) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto cfg = default_setup();
    const auto signal = white_noise_mono(256);

    EXPECT_THROW(iceberg::rendering::calibrate_ambisonics(
                     signal, 96.0, 45.0, cfg),
                 std::invalid_argument);
}

// Nearest-loudspeaker selection on the default layout: sources at 0 and 90 deg select the
// loudspeakers at those angles, whose level factors and filters differ, so the RMS of the
// two outputs must differ by more than 1e-4 of the larger one.
TEST(CalibrateAmbisonics, NspPicksExactCardinalLs) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    // Default layout [0, 90, 180, 270]. Source at 0° must pick the LS at 0°.
    // We confirm this indirectly by checking the level_factor applied:
    // newLevelFactor of LS 13 (the master-array index of angle 0°,
    // 1-based) is the only one that scales the output.
    const auto cfg = default_setup();
    const auto signal = white_noise_mono(1024, /*seed=*/7);

    const auto at_0  = iceberg::rendering::calibrate_ambisonics(
        signal, 80.0,   0.0, cfg);
    const auto at_90 = iceberg::rendering::calibrate_ambisonics(
        signal, 80.0,  90.0, cfg);

    // newLevelFactor(13) and newLevelFactor(19) are different, so the
    // outputs must differ in magnitude (different LS chosen).
    const double rms_0 =
        std::sqrt(at_0.samples.array().square().mean());
    const double rms_90 =
        std::sqrt(at_90.samples.array().square().mean());
    EXPECT_GT(std::abs(rms_0 - rms_90),
              1e-4 * std::max(rms_0, rms_90))
        << "rms_0=" << rms_0 << " rms_90=" << rms_90;
}

// The angular distance wraps around 360 deg: a source at 359 deg selects the loudspeaker
// at 0 deg, so its output must equal the output for 0 deg within 1e-6 (largest absolute
// difference).
TEST(CalibrateAmbisonics, NspWrapsAround) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    // Source at 359° has 1° distance to LS at 0°, not 359° to ch1 (180°).
    // Expect identical output to source = 0° (NSP picks LS 13 in both
    // cases — angular distance 1° vs 0° both map to ls_dir(0,:) = 0°).
    const auto cfg = default_setup();
    const auto signal = white_noise_mono(1024, /*seed=*/11);

    const auto at_0   = iceberg::rendering::calibrate_ambisonics(
        signal, 80.0,   0.0, cfg);
    const auto at_359 = iceberg::rendering::calibrate_ambisonics(
        signal, 80.0, 359.0, cfg);

    // Both should pick the same LS. Outputs identical (same filter,
    // same level factor). Float comparison.
    const double diff = (at_0.samples - at_359.samples)
                            .cwiseAbs().maxCoeff();
    record_measure("359 deg vs 0 deg", diff, 1e-6, "abs");
    EXPECT_NEAR(diff, 0.0, 1e-6);
}

// Edge case: an all-zero signal (RMS 0, so the RMS normalisation is skipped) at 80 dB SPL
// gives an all-zero output of the same shape, with no NaN or Inf from a division by zero.
TEST(CalibrateAmbisonics, AllZeroSignalProducesAllZeroOutput) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    // Exercises the `if (scaler != 0)` branch (scaler = 2*rms = 0,
    // so the RMS-normalisation step is skipped). Without coverage,
    // a regression that flips that guard could silently divide by
    // zero on quiet input.
    const auto cfg = default_setup();

    iceberg::Signal s;
    s.samples = Eigen::MatrixXf::Zero(1024, 1);
    s.sample_rate = kFs;

    const auto out = iceberg::rendering::calibrate_ambisonics(
        s, /*level_db=*/80.0, /*source_angle_deg=*/45.0, cfg);

    EXPECT_EQ(out.samples.rows(), 1024);
    EXPECT_EQ(out.samples.cols(), 1);
    EXPECT_FALSE(out.samples.array().isNaN().any());
    EXPECT_FALSE(out.samples.array().isInf().any());
    EXPECT_EQ(out.samples.cwiseAbs().maxCoeff(), 0.0f);
}

// A source equidistant from two loudspeakers takes the one reached first clockwise, as
// Iceberg MATLAB v1.0.0 computes it: on the default layout the outputs at 45, 135, 225
// and 315 deg must be bit-identical to those at 10, 100, 190 and 280 deg, which select
// the loudspeakers at 0, 90, 180 and 270 deg.
TEST(CalibrateAmbisonics, TieBreaksClockwise) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto cfg = default_setup();
    const auto signal = white_noise_mono(1024, /*seed=*/5);
    const auto at = [&](double deg) {
        return iceberg::rendering::calibrate_ambisonics(signal, 80.0, deg, cfg).samples;
    };
    EXPECT_TRUE(at(45.0) == at(10.0));
    EXPECT_TRUE(at(135.0) == at(100.0));
    EXPECT_TRUE(at(225.0) == at(190.0));
    EXPECT_TRUE(at(315.0) == at(280.0));
}

// === Against MATLAB: stages/rt_05/amb_calibrated_az_*.wav ==================

// signal.wav (already peak-normalised, as the render's dry input is) is calibrated at 30,
// 100 and 225 deg (a tie) and 80 dB SPL, and compared with the rt_05 stage files of
// Iceberg MATLAB v1.0.0 within 1e-10 RMS, the 32-bit float rounding of the reference.
TEST(CalibrateAmbisonics, StagesMatchMatlab) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto cfg = default_setup();
    const auto signal = iceberg::io::load_wav(iceberg::test::fixture_file("signal.wav"));
    double worst_rms = 0.0;
    for (const int angle : {30, 100, 225}) {
        char name[48];
        std::snprintf(name, sizeof(name), "stages/rt_05/amb_calibrated_az_%03d.wav", angle);
        const auto expected = iceberg::io::load_wav(iceberg::test::fixture_file(name));
        const auto out = iceberg::rendering::calibrate_ambisonics(signal, 80.0, angle, cfg);
        ASSERT_EQ(out.samples.rows(), expected.samples.rows());
        const auto d = iceberg::test::diff_stats(out.samples, expected.samples);
        EXPECT_LT(d.worst_rms, 1e-10) << angle;
        worst_rms = std::max(worst_rms, d.worst_rms);
    }
    record_measure("stages/rt_05 worst RMS (az 30, 100, 225)", worst_rms, 1e-10, "rms");
}

}  // namespace
